# 2. ANIMATION TOOLKIT (INTERPOLATE, SPRING PHYSICS, EASING & LIP-SYNC)
# ============================================================================

class Easing:
    """Kurva easing deterministik untuk animasi per-frame."""

    @staticmethod
    def linear(t: float) -> float:
        return t

    @staticmethod
    def in_quad(t: float) -> float:
        return t * t

    @staticmethod
    def out_quad(t: float) -> float:
        return 1.0 - (1.0 - t) * (1.0 - t)

    @staticmethod
    def in_out_quad(t: float) -> float:
        return 2.0 * t * t if t < 0.5 else 1.0 - ((-2.0 * t + 2.0) ** 2) / 2.0

    @staticmethod
    def in_cubic(t: float) -> float:
        return t * t * t

    @staticmethod
    def out_cubic(t: float) -> float:
        return 1.0 - ((1.0 - t) ** 3)

    @staticmethod
    def in_out_cubic(t: float) -> float:
        return 4.0 * t * t * t if t < 0.5 else 1.0 - ((-2.0 * t + 2.0) ** 3) / 2.0

    @staticmethod
    def out_back(t: float, s: float = 1.70158) -> float:
        u = t - 1.0
        return 1.0 + (s + 1.0) * (u ** 3) + s * (u ** 2)

    @staticmethod
    def out_bounce(t: float) -> float:
        n1, d1 = 7.5625, 2.75
        if t < 1.0 / d1:
            return n1 * t * t
        if t < 2.0 / d1:
            t -= 1.5 / d1
            return n1 * t * t + 0.75
        if t < 2.5 / d1:
            t -= 2.25 / d1
            return n1 * t * t + 0.9375
        t -= 2.625 / d1
        return n1 * t * t + 0.984375


def interpolate(
    value: float,
    input_range: Sequence[float],
    output_range: Sequence[float],
    easing: Optional[Callable[[float], float]] = None,
    clamp: bool = True,
) -> float:
    """Interpolasi multi-keyframe deterministik."""
    if len(input_range) < 2 or len(input_range) != len(output_range):
        raise ValueError("input_range dan output_range harus punya panjang >= 2 dan sama.")
    if clamp:
        if value <= input_range[0]:
            return float(output_range[0])
        if value >= input_range[-1]:
            return float(output_range[-1])
    seg = len(input_range) - 2
    for i in range(len(input_range) - 1):
        if value <= input_range[i + 1] or i == len(input_range) - 2:
            seg = i
            break
    in_a, in_b = float(input_range[seg]), float(input_range[seg + 1])
    out_a, out_b = float(output_range[seg]), float(output_range[seg + 1])
    t = 0.0 if abs(in_b - in_a) < 1e-9 else (value - in_a) / (in_b - in_a)
    if clamp:
        t = max(0.0, min(1.0, t))
    if easing is not None:
        t = easing(t)
    return out_a + (out_b - out_a) * t


def spring(
    frame: float,
    fps: float = 30.0,
    damping: float = 14.0,
    stiffness: float = 120.0,
    mass: float = 1.0,
    overshoot_clamping: bool = False,
) -> float:
    """Fisika pegas analitis (0.0 -> 1.0) deterministik untuk transisi & komedi."""
    if frame <= 0:
        return 0.0
    t = float(frame) / max(1.0, float(fps))
    m = max(1e-4, float(mass))
    k = max(1e-4, float(stiffness))
    c = max(0.0, float(damping))
    w0 = math.sqrt(k / m)
    zeta = c / (2.0 * math.sqrt(k * m))
    if zeta < 1.0 - 1e-6:
        wd = w0 * math.sqrt(1.0 - zeta * zeta)
        val = 1.0 - math.exp(-zeta * w0 * t) * (math.cos(wd * t) + (zeta * w0 / wd) * math.sin(wd * t))
    elif abs(zeta - 1.0) <= 1e-6:
        val = 1.0 - math.exp(-w0 * t) * (1.0 + w0 * t)
    else:
        sq = math.sqrt(zeta * zeta - 1.0)
        r1 = -w0 * (zeta - sq)
        r2 = -w0 * (zeta + sq)
        val = 1.0 - (r2 * math.exp(r1 * t) - r1 * math.exp(r2 * t)) / (r2 - r1)
    return max(0.0, min(1.0, val)) if overshoot_clamping else val


def extract_lipsync_curve(
    audio_path: str,
    fps: int = 30,
    smooth: float = 0.35,
    gain: float = 2.4,
) -> List[float]:
    """Ekstrak kurva bukaan mulut 0.0..1.0 per-frame dari file .wav / .mp3 / .m4a."""
    pcm_bytes = b""
    sample_rate = 16000
    if audio_path.lower().endswith(".wav"):
        with wave.open(audio_path, "rb") as wf:
            sample_rate = wf.getframerate()
            n_ch = wf.getnchannels()
            sw = wf.getsampwidth()
            raw = wf.readframes(wf.getnframes())
        if sw == 2 and n_ch == 1:
            pcm_bytes = raw
    if not pcm_bytes:
        ffmpeg_bin = shutil.which("ffmpeg")
        if not ffmpeg_bin:
            raise RuntimeError("FFmpeg diperlukan untuk membaca format audio non-WAV mono 16-bit.")
        proc = subprocess.run(
            [ffmpeg_bin, "-v", "error", "-i", audio_path, "-ac", "1", "-ar", str(sample_rate), "-f", "s16le", "-"],
            capture_output=True,
            check=True,
        )
        pcm_bytes = proc.stdout
    samples = array.array("h")
    samples.frombytes(pcm_bytes[: len(pcm_bytes) - (len(pcm_bytes) % 2)])
    if not samples:
        return [0.0]
    step = max(1, int(round(sample_rate / max(1, fps))))
    rms_vals: List[float] = []
    for start in range(0, len(samples), step):
        chunk = samples[start : start + step]
        if not chunk:
            break
        rms = math.sqrt(sum(s * s for s in chunk) / len(chunk)) / 32768.0
        rms_vals.append(rms)
    peak = max(rms_vals) if rms_vals else 1.0
    norm_div = max(peak, 0.05)
    curve: List[float] = []
    prev = 0.0
    for r in rms_vals:
        target = max(0.0, min(1.0, (r / norm_div) * gain))
        if target < 0.08:
            target = 0.0
        cur = prev * smooth + target * (1.0 - smooth)
        curve.append(round(cur, 4))
        prev = cur
    return curve

