def traceTwoBonePath(ctx, p0, p1, p2, roundness=None):
    r = (roundness or 0.25)
    m1x = (p1.x + (((p0.x - p1.x)) * r))
    m1y = (p1.y + (((p0.y - p1.y)) * r))
    m2x = (p1.x + (((p2.x - p1.x)) * r))
    m2y = (p1.y + (((p2.y - p1.y)) * r))
    ctx.beginPath()
    ctx.moveTo(p0.x, p0.y)
    ctx.lineTo(m1x, m1y)
    ctx.quadraticCurveTo(p1.x, p1.y, m2x, m2y)
    ctx.lineTo(p2.x, p2.y)

def drawArticulatedLeg(ctx, hip, knee, ankle, toe, rimI, limbColor=None):
    col = (limbColor or '#1F161E')
