def drawHeadwear(ctx, cfg, deg, s, c, pose, rimI):
    hat = (cfg.hat or 'none')
    isEnclosed = ((hat == 'astronaut_helmet') or (hat == 'hood'))
    hatTiltDeg = (((((cfg.hatTilt or 0)) + ((pose.hatTiltExtra or 0)))) * ((0.18 if isEnclosed else 1)))
    hatLiftY = (((((cfg.hatLiftY or 0)) + ((pose.hatLiftExtra or 0)))) * ((0.12 if isEnclosed else 1)))
    pivotY = (150 if isEnclosed else 96)
    if (hat == 'welding_goggles'):
        if (cfg.backHair == 'windswept_bolt'):
            drawWindsweptBoltHair(ctx, cfg, deg, s, c, pose, rimI)
        elif (cfg.backHair != 'bald'):
            drawHeadwear(ctx, _AttrDict({**(cfg), 'hat': 'none', 'hatTilt': 0, 'hatLiftY': 0}), deg, s, c, pose, rimI)
        ctx.save()
        ctx.translate(104, (pivotY - (hatLiftY * 0.45)))
        ctx.rotate((((hatTiltDeg * math.pi)) / 180))
        ctx.translate((-104), (-pivotY))
        drawWeldingGoggles(ctx, cfg, deg, s, c, pose, rimI)
        ctx.restore()
        return
    ctx.save()
    ctx.translate(104, (pivotY - hatLiftY))
    ctx.rotate((((hatTiltDeg * math.pi)) / 180))
    ctx.translate((-104), (-pivotY))
    if (hat == 'none'):
        if (cfg.backHair == 'windswept_bolt'):
            drawWindsweptBoltHair(ctx, cfg, deg, s, c, pose, rimI)
            ctx.restore()
            return
        hGrad = ctx.createLinearGradient(44, 54, 168, 114)
        hGrad.addColorStop(0, shadeHex(cfg.hairColor, 0.52))
        hGrad.addColorStop(0.48, cfg.hairColor)
        hGrad.addColorStop(0.78, tintHex(cfg.hairColor, 0.36))
        hGrad.addColorStop(1, shadeHex(cfg.hairColor, 0.62))
        if (cfg.backHair == 'chonmage'):
            kx = (104 - (8 * s))
            ctx.fillStyle = '#1B131C'
            ctx.beginPath()
            ctx.ellipse(kx, 87, 14, 9.2, ((-0.15) * c), 0, (math.pi * 2))
            ctx.fill()
            kG = ctx.createRadialGradient((kx + 3), 83, 1.5, kx, 87, 12)
            kG.addColorStop(0, tintHex(cfg.hairColor, 0.42))
            kG.addColorStop(0.55, cfg.hairColor)
            kG.addColorStop(1, shadeHex(cfg.hairColor, 0.45))
            ctx.fillStyle = kG
            ctx.beginPath()
            ctx.ellipse((kx + 1), 86, 11, 6.8, ((-0.15) * c), 0, (math.pi * 2))
            ctx.fill()
            ctx.strokeStyle = cfg.hatAccent
            ctx.lineWidth = 3.2
            ctx.lineCap = 'round'
            ctx.beginPath()
            ctx.moveTo((kx - 8), 92.5)
            ctx.lineTo((kx + 8), 92.5)
            ctx.stroke()
        elif (cfg.backHair == 'spiky'):
            ctx.fillStyle = 'rgba(26, 14, 24, 0.25)'
            ctx.beginPath()
            ctx.ellipse(104, 104, 58, 9, 0, 0, (math.pi * 2))
            ctx.fill()
            ctx.fillStyle = hGrad
            ctx.strokeStyle = '#1B131C'
            ctx.lineWidth = 3.4
            ctx.lineJoin = 'round'
            ctx.beginPath()
            ctx.moveTo(44, 108)
            ctx.lineTo(52, 70)
            ctx.lineTo(72, 87)
            ctx.lineTo(94, 54)
            ctx.lineTo(112, 80)
            ctx.lineTo(137, 58)
            ctx.lineTo(149, 85)
            ctx.lineTo(170, 74)
            ctx.lineTo(165, 108)
            ctx.quadraticCurveTo(104, 96, 44, 108)
            ctx.closePath()
            ctx.fill()
            ctx.stroke()
            ctx.strokeStyle = shadeHex(cfg.hairColor, 0.42)
            ctx.lineWidth = 1.7
            ctx.lineCap = 'round'
            ctx.beginPath()
            ctx.moveTo(72, 87)
            ctx.lineTo(78, 98)
            ctx.moveTo(112, 80)
            ctx.lineTo(114, 96)
            ctx.moveTo(149, 85)
            ctx.lineTo(142, 98)
            ctx.stroke()
            ctx.strokeStyle = f"rgba(255, 244, 230, {(0.42 * rimI)})"
            ctx.lineWidth = 3.2
            ctx.beginPath()
            ctx.moveTo(86, 76)
            ctx.quadraticCurveTo(118, 70, 148, 84)
            ctx.stroke()
        elif (cfg.backHair == 'curly'):
            puffs = [[58, 92, 22], [84, 79, 25], [116, 78, 26], [146, 90, 22], [103, 88, 23]]
            for i in range(len(puffs)):
                px = puffs[i][0]
                py = puffs[i][1]
                pr = puffs[i][2]
                pG = ctx.createRadialGradient((px + (pr * 0.3)), (py - (pr * 0.35)), 2, px, py, pr)
                pG.addColorStop(0, tintHex(cfg.hairColor, 0.38))
                pG.addColorStop(0.55, cfg.hairColor)
                pG.addColorStop(1, shadeHex(cfg.hairColor, 0.46))
                ctx.fillStyle = pG
                ctx.strokeStyle = '#1B131C'
