def drawCustomLayers(ctx, layers, targetLayer):
    if ((not layers) or (len(layers) == 0)):
        return
    for i in range(len(layers)):
        item = layers[i]
        if ((not item) or (item.layer != targetLayer)):
            continue
        ctx.save()
        if _is_num(item.opacity):
            ctx.globalAlpha = item.opacity
        if item.fill:
            ctx.fillStyle = item.fill
        if item.stroke:
            ctx.strokeStyle = item.stroke
        if _is_num(item.lineWidth):
            ctx.lineWidth = item.lineWidth
        ctx.lineCap = 'round'
        ctx.lineJoin = 'round'
        if (item.type == 'circle'):
            ctx.beginPath()
            ctx.arc((item.x or 104), (item.y or 150), (item.r or 10), 0, (math.pi * 2))
            if item.fill:
                ctx.fill()
            if item.stroke:
                ctx.stroke()
        elif (item.type == 'ellipse'):
            ctx.beginPath()
            ctx.ellipse((item.x or 104), (item.y or 150), (item.rx or 12), (item.ry or 8), (item.rot or 0), 0, (math.pi * 2))
            if item.fill:
                ctx.fill()
            if item.stroke:
                ctx.stroke()
        elif (item.type == 'rect'):
            ctx.beginPath()
            ctx.roundRect((item.x or 90), (item.y or 220), (item.w or 28), (item.h or 18), (item.radius or 4))
            if item.fill:
                ctx.fill()
            if item.stroke:
                ctx.stroke()
        elif (item.type == 'line'):
            ctx.beginPath()
            ctx.moveTo((item.x or 90), (item.y or 220))
            ctx.lineTo((item.x2 or 120), (item.y2 or 220))
            ctx.stroke()
        ctx.restore()

def renderCharacterCanvas(ctx, rawConfig, viewAngleDeg, animMode, t, options=None):
    rawConfig = _wrap(rawConfig) if rawConfig is not None else None
    options = _wrap(options) if options is not None else _AttrDict()
    baseCfg = _AttrDict({**(DEFAULT_CONFIG), **(((rawConfig or _AttrDict({}))))})
    opts = (options or _AttrDict({}))
    ov = (opts.overrides or _AttrDict({}))
    cfg = _AttrDict({**(baseCfg), 'eyes': (ov.eyes or baseCfg.eyes), 'eyebrows': (ov.eyebrows or baseCfg.eyebrows), 'mouth': (ov.mouth or baseCfg.mouth), 'prop': (ov.prop if isinstance(ov.prop, str) else baseCfg.prop), 'sweatDrop': (ov.sweatDrop if isinstance(ov.sweatDrop, bool) else baseCfg.sweatDrop), 'blush': (ov.blush if isinstance(ov.blush, bool) else baseCfg.blush), 'angerVein': (ov.angerVein if isinstance(ov.angerVein, bool) else baseCfg.angerVein), 'hatTilt': (ov.hatTilt if _is_num(ov.hatTilt) else baseCfg.hatTilt), 'hatLiftY': (ov.hatLiftY if _is_num(ov.hatLiftY) else baseCfg.hatLiftY), 'groundShadow': (ov.groundShadow if isinstance(ov.groundShadow, bool) else baseCfg.groundShadow), 'outlineShadow': 1.35, 'outlineLit': 1.0, 'rimIntensity': 0.45, 'shadowDepth': 1.5})
    scale = (opts.scale or 2)
    hideHat = (not (not opts.hideHat))
    flipX = (not (not opts.flipX))
    deg = (((((viewAngleDeg % 360)) + 360)) % 360)
    rad = (((deg * math.pi)) / 180)
    s = math.sin(rad)
    c = math.cos(rad)
    pose = computeSkeletonPose(cfg, (animMode or 'idle'), (t or 0), ov)
    if (animMode == 'run'):
        pose.torsoLeanZ += (s * 0.06)
    elif (animMode == 'walk'):
        pose.torsoLeanZ += (s * 0.025)
    leanSin = math.sin(pose.torsoLeanZ)
    leanCos = math.cos(pose.torsoLeanZ)
    neckDx = (118 * leanSin)
    neckDy = (118 * ((1 - leanCos)))
    shDx = (110 * leanSin)
    shDy = (110 * ((1 - leanCos)))
    beltDx = (50 * leanSin)
    beltDy = (50 * ((1 - leanCos)))
    relHeadBobY = max(0, min(4.5, (pose.headBobY - pose.pelvisY)))
    rimI = cfg.rimIntensity
    shD = cfg.shadowDepth
    activeEyes = (pose.overrideEyes or cfg.eyes)
    ctx.save()
    ctx.setTransform(scale, 0, 0, scale, 0, 0)
    ctx.clearRect(0, 0, 240, 520)
    if flipX:
        ctx.translate(240, 0)
        ctx.scale((-1), 1)
    if (cfg.groundShadow != False):
        hFactor = max(0.35, (1 - (pose.jumpHeight / 140)))
        sg = ctx.createRadialGradient(OX, 480, 6, OX, 480, (62 * hFactor))
        sg.addColorStop(0, f"rgba(20, 14, 24, {(0.32 * hFactor)})")
        sg.addColorStop(1, 'rgba(20, 14, 24, 0)')
        ctx.fillStyle = sg
        ctx.beginPath()
        ctx.ellipse(OX, 480, (62 * hFactor), (13 * hFactor), 0, 0, (math.pi * 2))
        ctx.fill()
    ctx.save()
    ctx.translate(OX, 476)
    ctx.scale(pose.squashX, pose.squashY)
    ctx.translate((-OX), (-476))
    drawCustomLayers(ctx, cfg.customLayers, 'back')
    drawCapeOrBackItem(ctx, cfg, s, c, pose, rimI, True)
    pLHip = rot3D(pose.lHip.x, pose.lHip.y, pose.lHip.z, s, c)
    pLKnee = rot3D(pose.lKnee.x, pose.lKnee.y, pose.lKnee.z, s, c)
    pLAnkle = rot3D(pose.lAnkle.x, pose.lAnkle.y, pose.lAnkle.z, s, c)
    pLToe = rot3D(pose.lToe.x, pose.lToe.y, pose.lToe.z, s, c)
    lFootDy = (((pLAnkle.z - ((-10)))) * 0.35)
    pLAnkle.y += lFootDy
    pLToe.y += (lFootDy + (((pLToe.z - 8)) * 0.14))
    pLKnee.y += (lFootDy * 0.45)
    pRHip = rot3D(pose.rHip.x, pose.rHip.y, pose.rHip.z, s, c)
    pRKnee = rot3D(pose.rKnee.x, pose.rKnee.y, pose.rKnee.z, s, c)
    pRAnkle = rot3D(pose.rAnkle.x, pose.rAnkle.y, pose.rAnkle.z, s, c)
    pRToe = rot3D(pose.rToe.x, pose.rToe.y, pose.rToe.z, s, c)
    rFootDy = (((pRAnkle.z - 10)) * 0.35)
    pRAnkle.y += rFootDy
    pRToe.y += (rFootDy + (((pRToe.z - 28)) * 0.14))
    pRKnee.y += (rFootDy * 0.45)
    if (pLAnkle.z < pRAnkle.z):
        drawArticulatedLeg(ctx, pLHip, pLKnee, pLAnkle, pLToe, rimI, cfg.limbColor)
        drawArticulatedLeg(ctx, pRHip, pRKnee, pRAnkle, pRToe, rimI, cfg.limbColor)
    else:
        drawArticulatedLeg(ctx, pRHip, pRKnee, pRAnkle, pRToe, rimI, cfg.limbColor)
        drawArticulatedLeg(ctx, pLHip, pLKnee, pLAnkle, pLToe, rimI, cfg.limbColor)
    pLaSh = rot3D(pose.laSh.x, pose.laSh.y, pose.laSh.z, s, c)
    pLaElb = rot3D(pose.laElb.x, pose.laElb.y, pose.laElb.z, s, c)
    pLaHnd = rot3D(pose.laHnd.x, pose.laHnd.y, pose.laHnd.z, s, c)
    pLaSh.x += shDx
    pLaSh.y += shDy
    pLaElb.x += (shDx * 0.65)
    pLaElb.y += (shDy * 0.65)
    pLaHnd.x += (shDx * 0.35)
